verify.cmd:
node -e 'const fs=require("fs"),os=require("os"),path=require("path"),{spawnSync}=require("child_process")
const fail=(m)=>{console.error("HYG-148 FAILED: "+m);process.exit(1)}
let L;try{L=require("./scripts/lib/ledger.mjs")}catch(e){process.exit(79)}
if(typeof L.compactLedger!=="function")fail("scripts/lib/ledger.mjs has no compactLedger, so fragments can only pile up")
const cli=path.resolve("scripts/ledger.mjs")
const dir=fs.mkdtempSync(path.join(os.tmpdir(),"hyg148-"))
const w=(rel,t)=>{fs.mkdirSync(path.dirname(path.join(dir,rel)),{recursive:true});fs.writeFileSync(path.join(dir,rel),t)}
const run=(args)=>spawnSync(process.execPath,[cli].concat(args),{cwd:dir,encoding:"utf8"})
let before,after,first,second,closed,left
try{
const row=(id)=>({id:id,title:id,status:"open",lane:"live",detail:"d."})
w("docs/BUILD-BACKLOG.json",JSON.stringify({meta:{slate:{waves:[{name:"W1 · x",ids:["A-1","B-1"]}]}},entries:[row("A-1"),row("B-1")]},null,2))
w("docs/DECISIONS.md","# L\n\n## ADR-001: one\n")
w("docs/ledger/adr/ADR-002.md","## ADR-002: two\n")
w("probe.txt","node -e \"process.exit(0)\"\n")
closed=run(["close","A-1","--verify-file","probe.txt","--note","CLOSED."])
before=JSON.stringify([L.loadBacklog(dir),L.loadDecisions(dir)])
first=run(["compact"])
after=JSON.stringify([L.loadBacklog(dir),L.loadDecisions(dir)])
left=L.fragmentCount(dir).n
const bytes=fs.readFileSync(path.join(dir,"docs/BUILD-BACKLOG.json"),"utf8")+fs.readFileSync(path.join(dir,"docs/DECISIONS.md"),"utf8")
second=run(["compact"])
second.same=bytes===fs.readFileSync(path.join(dir,"docs/BUILD-BACKLOG.json"),"utf8")+fs.readFileSync(path.join(dir,"docs/DECISIONS.md"),"utf8")
}finally{fs.rmSync(dir,{recursive:true,force:true})}
if([closed,first,second].some((r)=>r.error||r.signal))process.exit(79)
if(closed.status!==0)fail("ledger:close did not write a fragment: "+closed.stderr)
if(!before.includes("\"closed\":")||!before.includes("CLOSED."))fail("the fragment ledger:close wrote does not close the row in the merged view")
if(first.status!==0)fail("ledger:compact failed: "+first.stderr)
if(left!==0)fail("ledger:compact left "+left+" fragment(s) behind")
if(before!==after)fail("the merged view changed across compaction")
if(second.status!==0||!second.same)fail("a second compaction changed the base files, so compaction is not byte-stable")
const real=L.loadBacklog(".")
const RAW=/readFileSync\(\s*\\?["\x27]docs\/BUILD-BACKLOG\.json|require\(\s*\\?["\x27]\.\/docs\/BUILD-BACKLOG\.json|readFileSync\(B,/
const raw=["PROG-D5","PROG-D6","PROG-D7","PROG-R10","DEF-HARDEN","HYG-047","HYG-124","LIVE-034","HYG-108","LIVE-176","HYG-023","LIVE-447","LIVE-478"].filter((id)=>{const e=real.entries.find((x)=>x.id===id);return e&&e.verify&&RAW.test(String(e.verify.cmd||""))})
if(raw.length)fail("these probes still parse the raw backlog file and misread a fragment-closed row: "+raw.join(", "))
console.log("HYG-148 ok: ledger:close writes a closing fragment, ledger:compact folds every fragment with the merged view unchanged and is byte-stable, and no ledger-reading probe parses the raw file")'
